function validateBasicDraft(){var d=state.basicDraft,errors={};[['name','产品名称'],['model','产品型号'],['displayModel','显示型号'],['app','所属App']].forEach(function(pair){if(!String(d[pair[0]]||'').trim())errors[pair[0]]='请填写'+pair[1]});if(!d.methods.length)errors.methods='请选择配网方式';if(d.communication.includes('WIFI')&&!d.band)errors.band='请选择支持频段';if(!d.productImage)errors.productImage='请选择产品图片源图';return errors}
