 if(action==='draft'){var nextDrafts=JSON.parse(JSON.stringify(state.basicLocalDrafts));nextDrafts[state.productCode]=data;try{localStorage.setItem(basicDraftStorage,JSON.stringify(nextDrafts))}catch(e){toast('本地草稿保存失败，请重试。','error');return}state.basicLocalDrafts=nextDrafts;closeDrawer();render();toast('本地草稿已保存（原型模拟，未更新生效配置）','success')}
